import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FiUser, FiMail, FiPhone, FiMapPin, FiEdit2, FiPackage, FiHeart, FiLogOut } from 'react-icons/fi';
import { useAuth } from '../contexts/AuthContext';
import Header from '../components/Header';
import Footer from '../components/Footer';
import toast from 'react-hot-toast';

const UserProfile = () => {
  const { user, isAuthenticated, updateProfile, logout } = useAuth();
  const navigate = useNavigate();
  const [editing, setEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: user?.name || '',
    email: user?.email || '',
    phone: user?.phone || '',
    address: user?.address?.addressLine || '',
    city: user?.address?.city || '',
    state: user?.address?.state || '',
    pincode: user?.address?.pincode || '',
  });

  if (!isAuthenticated) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
        <Header />
        <main className="container page-wrapper">
          <div className="empty-state">
            <FiUser style={{ fontSize: '64px', color: 'var(--text-light)', marginBottom: '16px' }} />
            <h3>Please login to view profile</h3>
            <Link to="/login" className="btn btn-primary">Login</Link>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  const handleSave = async () => {
    const result = await updateProfile({
      name: formData.name,
      phone: formData.phone,
      address: { addressLine: formData.address, city: formData.city, state: formData.state, pincode: formData.pincode },
    });
    if (result.success) setEditing(false);
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const menuItems = [
    { icon: <FiPackage />, label: 'My Orders', path: '/orders' },
    { icon: <FiHeart />, label: 'Wishlist', path: '/wishlist' },
  ];

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header />
      <main style={{ flex: 1 }}>
        <div className="container page-wrapper">
          <div style={{ display: 'grid', gridTemplateColumns: '250px 1fr', gap: '16px', alignItems: 'start' }} className="profile-grid">
            <div className="card" style={{ padding: '20px' }}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', marginBottom: '20px' }}>
                <div style={{ width: '64px', height: '64px', borderRadius: '50%', background: 'var(--primary)', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '24px', fontWeight: 700, marginBottom: '12px' }}>
                  {(user?.name || 'U').charAt(0).toUpperCase()}
                </div>
                <h3 style={{ fontSize: '16px', fontWeight: 600 }}>{user?.name}</h3>
                <p style={{ fontSize: '13px', color: 'var(--text-light)' }}>{user?.email}</p>
              </div>
              <nav style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                {menuItems.map((item) => (
                  <Link key={item.path} to={item.path} style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '10px 12px', borderRadius: '4px', fontSize: '14px', color: 'var(--text-primary)', transition: 'background 0.2s' }}>
                    {item.icon} {item.label}
                  </Link>
                ))}
                <button onClick={handleLogout} style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '10px 12px', borderRadius: '4px', fontSize: '14px', color: 'var(--danger)', cursor: 'pointer', background: 'none', textAlign: 'left' }}>
                  <FiLogOut /> Logout
                </button>
              </nav>
            </div>

            <div className="card" style={{ padding: '24px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                <h2 style={{ fontSize: '18px', fontWeight: 600 }}>Profile Information</h2>
                {!editing && (
                  <button onClick={() => setEditing(true)} className="btn btn-outline btn-sm"><FiEdit2 size={14} /> Edit</button>
                )}
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
                <div className="input-group">
                  <label><FiUser size={14} style={{ marginRight: '6px' }} />Full Name</label>
                  <input className="input" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} disabled={!editing} />
                </div>
                <div className="input-group">
                  <label><FiMail size={14} style={{ marginRight: '6px' }} />Email</label>
                  <input className="input" value={formData.email} disabled style={{ background: 'var(--bg-primary)' }} />
                </div>
                <div className="input-group">
                  <label><FiPhone size={14} style={{ marginRight: '6px' }} />Phone</label>
                  <input className="input" value={formData.phone} onChange={(e) => setFormData({ ...formData, phone: e.target.value })} disabled={!editing} />
                </div>
                <div className="input-group" style={{ gridColumn: 'span 2' }}>
                  <label><FiMapPin size={14} style={{ marginRight: '6px' }} />Address</label>
                  <textarea className="input" rows={2} value={formData.address} onChange={(e) => setFormData({ ...formData, address: e.target.value })} disabled={!editing} />
                </div>
                <div className="input-group">
                  <label>City</label>
                  <input className="input" value={formData.city} onChange={(e) => setFormData({ ...formData, city: e.target.value })} disabled={!editing} />
                </div>
                <div className="input-group">
                  <label>State</label>
                  <input className="input" value={formData.state} onChange={(e) => setFormData({ ...formData, state: e.target.value })} disabled={!editing} />
                </div>
                <div className="input-group">
                  <label>Pincode</label>
                  <input className="input" value={formData.pincode} onChange={(e) => setFormData({ ...formData, pincode: e.target.value })} disabled={!editing} />
                </div>
              </div>

              {editing && (
                <div style={{ display: 'flex', gap: '12px', marginTop: '24px' }}>
                  <button onClick={handleSave} className="btn btn-primary">Save Changes</button>
                  <button onClick={() => setEditing(false)} className="btn btn-outline">Cancel</button>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>
      <Footer />
      <style>{`@media (max-width: 768px) { .profile-grid { grid-template-columns: 1fr !important; } }`}</style>
    </div>
  );
};

export default UserProfile;
